use nocturne_native::NativeScene;
#[test]fn original_stage_queries(){let mut s=NativeScene::new(42).unwrap();s.command(r#"{"op":"source-stage-component","id":1,"legacyFlags":100001,"kind":"button","x":2,"y":3,"width":10,"height":3}"#).unwrap();let before=s.snapshot().unwrap();assert_eq!(s.source_stage_tween(-200,1000,210,420,1).unwrap(),400);assert_eq!(s.source_stage_ink_opacity(420,420,768,1536,760).unwrap(),880);assert_eq!(s.source_stage_hit(3,4).unwrap(),Some([100001,0]));assert_eq!(s.source_stage_hit(-1,-1).unwrap(),None);assert!(s.source_stage_tween(0,100,5,10,4).is_err());assert!(s.source_stage_ink_opacity(0,0,0,-1,0).is_err());assert_eq!(before,s.snapshot().unwrap());}
